<?php $pageTitle=page_title('Product categories'); $page='admin-categories'; ?>
<div class="dashboard-head reveal"><div><span class="eyebrow">Master data</span><h1>Product categories</h1><p>Keep browse filters simple and farmer listings consistent.</p></div></div>
<div class="detail-grid"><div class="content-card card"><div class="content-head"><div><h2>Current categories</h2><p>Deactivate rather than delete categories with products.</p></div></div><div class="table-wrap"><table><thead><tr><th>Category</th><th>Products</th><th>Active</th><th>Order</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($categories as $category): ?><tr><td><strong><?= e($category['name']) ?></strong><br><small class="text-muted"><?= e($category['description']) ?></small></td><td><?= (int)$category['product_count'] ?></td><td><?= (int)$category['active_product_count'] ?></td><td><?= (int)$category['sort_order'] ?></td><td><?= status_pill($category['status']) ?></td><td><a class="icon-btn" href="#edit-<?= (int)$category['id'] ?>"><?= icon('edit') ?></a></td></tr><?php endforeach; ?></tbody></table></div></div>
<form class="content-card card" method="post" action="<?= e(url('admin-category-save')) ?>"><?= csrf_field() ?><div class="content-head"><div><h2>Add category</h2><p>Create a new farmer listing category.</p></div><span class="feature-icon" style="margin:0"><?= icon('plus') ?></span></div><div class="form-group"><label for="new_category_name">Name</label><input id="new_category_name" name="name" type="text" maxlength="80" required></div><div class="form-group"><label for="new_category_description">Description</label><textarea id="new_category_description" name="description" maxlength="300"></textarea></div><div class="form-grid"><div class="form-group"><label for="new_category_sort">Sort order</label><input id="new_category_sort" name="sort_order" type="number" value="10" min="0" max="999"></div><div class="form-group"><label for="new_category_status">Status</label><select id="new_category_status" name="status"><option value="active">Active</option><option value="inactive">Inactive</option></select></div></div><button class="btn" type="submit">Add category</button></form></div>
<div class="content-card card mt-3"><div class="content-head"><div><h2>Edit categories</h2><p>Update names, descriptions, status, and display order.</p></div></div><div class="review-grid"><?php foreach($categories as $category): ?><form class="card card-pad" id="edit-<?= (int)$category['id'] ?>" method="post" action="<?= e(url('admin-category-save')) ?>"><?= csrf_field() ?><input type="hidden" name="category_id" value="<?= (int)$category['id'] ?>"><div class="form-group"><label>Name</label><input name="name" type="text" value="<?= e($category['name']) ?>" maxlength="80" required></div><div class="form-group"><label>Description</label><textarea name="description" maxlength="300"><?= e($category['description']) ?></textarea></div><div class="form-grid"><div class="form-group"><label>Sort</label><input name="sort_order" type="number" value="<?= (int)$category['sort_order'] ?>" min="0"></div><div class="form-group"><label>Status</label><select name="status"><option value="active" <?= $category['status']==='active'?'selected':'' ?>>Active</option><option value="inactive" <?= $category['status']==='inactive'?'selected':'' ?>>Inactive</option></select></div></div><button class="btn btn-light btn-sm" type="submit">Save changes</button></form><?php endforeach; ?></div></div>
